3. Hence Stack / Registers are NOT shared.$q$, $q${"A":"Correct shared resource set.","B":"Omits open files.","C":"Identifies private state.","D":"Incorrectly claims stack is shared."}$q$::jsonb, ARRAY[$q$Thread Memory Model$q$,$q$Shared vs Private Resources$q$,$q$Concurrency$q$]::text[], ARRAY[$q$Thread State = Private Stack + Private Registers$q$]::text[], ARRAY[$q$Stack is private per thread for local function call frames.$q$]::text[], 'Easy', $q$Thinking stack space is shared across threads.$q$, $q$Threads All GATE Questions | L 8$q$, 'Verified', $q$[{"code":"TEMPLATE_FAMILY","severity":"info","message":"One of several questions with near-identical wording in this dataset (only numbers, year or format differ)."}]$q$::jsonb);
